-- 2026-10-18 ERP只读预检；仅供另行授权的操作者核实，不由开发工具执行。
-- 不建立连接、不改表、不修复、不切换STRICT。先核对目标及导出边界。
SELECT DATABASE() AS selected_database,@@server_uuid AS server_uuid,VERSION() AS mysql_version;
SELECT TABLE_NAME,ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('wm_barcode','bd_material','bd_serial_number_rule','wm_sn','wm_material_stock','wm_material_stock_tx','wm_serial_reservation','wm_serial_lifecycle_command','wm_serial_sequence','wm_sn_alias','wm_document_sn','wm_trace_posting_group','wm_valuation_group','wm_trace_outbox','wm_trace_inbox','wm_trace_repair_run','wm_trace_repair_item','wm_trace_audit_run','wm_trace_material_reservation','wm_trace_material_reservation_line','wm_trace_material_consumption','wm_trace_stock_conversion_run','wm_work_order_tracking_policy','wm_work_order_policy_adoption');
SELECT TABLE_NAME,COLUMN_NAME,COLUMN_TYPE,IS_NULLABLE,COLUMN_DEFAULT,COLLATION_NAME,EXTRA,GENERATION_EXPRESSION FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('wm_barcode','bd_material','bd_serial_number_rule','wm_sn','wm_material_stock','wm_material_stock_tx','wm_serial_reservation','wm_serial_lifecycle_command','wm_serial_sequence','wm_sn_alias','wm_document_sn','wm_trace_posting_group','wm_valuation_group','wm_trace_outbox','wm_trace_inbox','wm_trace_repair_run','wm_trace_repair_item','wm_trace_audit_run','wm_trace_material_reservation','wm_trace_material_reservation_line','wm_trace_material_consumption','wm_trace_stock_conversion_run','wm_work_order_tracking_policy','wm_work_order_policy_adoption') ORDER BY TABLE_NAME,ORDINAL_POSITION;
SELECT TABLE_NAME,INDEX_NAME,NON_UNIQUE,SEQ_IN_INDEX,COLUMN_NAME,SUB_PART FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('wm_barcode','bd_material','bd_serial_number_rule','wm_sn','wm_material_stock','wm_material_stock_tx','wm_serial_reservation','wm_serial_lifecycle_command','wm_serial_sequence','wm_sn_alias','wm_document_sn','wm_trace_posting_group','wm_valuation_group','wm_trace_outbox','wm_trace_inbox','wm_trace_repair_run','wm_trace_repair_item','wm_trace_audit_run','wm_trace_material_reservation','wm_trace_material_reservation_line','wm_trace_material_consumption','wm_trace_stock_conversion_run','wm_work_order_tracking_policy','wm_work_order_policy_adoption') ORDER BY TABLE_NAME,INDEX_NAME,SEQ_IN_INDEX;
-- 旧版重复只报告，不能据此自动升级或补造单件。
SELECT tenant_id,sn_id,COUNT(*) AS active_rows,SUM(stock_quantity) AS quantity FROM wm_material_stock WHERE stock_quantity>0 AND sn_id IS NOT NULL GROUP BY tenant_id,sn_id HAVING COUNT(*)>1;
SELECT s.tenant_id,s.stock_id,s.material_id,s.sn_id,s.stock_quantity FROM wm_material_stock s JOIN bd_material m ON m.tenant_id=s.tenant_id AND m.material_id=s.material_id WHERE m.is_serial_manage=1 AND s.stock_quantity>0 AND (s.sn_id IS NULL OR s.stock_quantity<>1);
SET @trace_preflight_sql=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='wm_material_stock' AND COLUMN_NAME='tracking_version')=1,'SELECT tenant_id,sn_id,COUNT(*) AS conflicting_rows FROM wm_material_stock WHERE tracking_version>=2 AND stock_quantity>0 AND sn_id IS NOT NULL GROUP BY tenant_id,sn_id HAVING COUNT(*)>1','SELECT ''旧基线尚无tracking_version，新增默认1不会升级旧库存'' AS preflight_note');
PREPARE trace_preflight_stmt FROM @trace_preflight_sql;
EXECUTE trace_preflight_stmt;
DEALLOCATE PREPARE trace_preflight_stmt;
